            s = digits[:5]
        else:
            s = (digits + '0' * (5 - len(digits)))[:5]
    chars = list(s)
    # Introduce 1 or 2 "x" corruptions within the 5 characters
    reps = random.randint(1, 2)
    idxs = random.sample(range(5), reps)
