        mapping = {'o': '0', 'l': '1', 'i': '1', 'a': 'x', 'e': 'x', 't': '7', 's': 'z'}
        if not x:
            return x
        i = random.randrange(len(x))
        ch = x[i]
        low = ch.lower()
        if low in mapping:
            rep = mapping[low]
            if ch.isupper():
                rep = rep.upper()
            return x[:i] + rep + x[i + 1:]
        return x

    def add_space_error(x: str) -> str:
        if ' - ' in x and random.random() < 0.5:
            return x.replace(' - ', '-')
        if '-' in x and random.random() < 0.5:
            return x.replace('-', ' - ')
        return x

