import string

def corrupt(cell: str) -> str:
    """
    Given a CLEAN value (e.g., '0%', '75%', '100%'), return a DIRTY version
    imitating common corruption seen in the column.
    """
    if not isinstance(cell, str):
        cell = str(cell)
    s = cell

    strategies = [
        'space',
        'remove_percent',
        'digit_replace',
        'prefix_x',
        'suffix_x',
        'insert_extra',
        'swap_percent_with_x',
    ]
    strat = random.choice(strategies)

    if strat == 'space':
        if '%' in s:
            s = s.replace('%', ' %')
        else:
            s = s + ' %'
    elif strat == 'remove_percent':
        s = s.replace('%', '')
    elif strat == 'digit_replace':
        digits = [i for i, ch in enumerate(s) if ch.isdigit()]
        if digits:
            i = random.choice(digits)
            s = s[:i] + random.choice(string.ascii_letters) + s[i+1:]
        else:
            s = 'x' + s
    elif strat == 'prefix_x':
        s = 'x' + s
    elif strat == 'suffix_x':
        s = s + 'x'
    elif strat == 'insert_extra':
        digits = [i for i, ch in enumerate(s) if ch.isdigit()]
        if digits:
            i = random.choice(digits)
            s = s[:i+1] + random.choice(['!', '@', '#', '$', '%', '&', '*']) + s[i+1:]
        else:
            s = s + random.choice(['!', '?'])
    elif strat == 'swap_percent_with_x':
        if '%' in s:
            s = s.replace('%', 'x%', 1)
        else:
            s = 'x' + s

    return s

