    Return a dirty variant of a clean cell by applying a plausible corruption.
    The corruption aims to produce strings not matching the clean patterns.
    """
    s = cell

    def sub_char(st: str) -> str:
        if not st:
            return random.choice('abcdefghijklmnopqrstuvwxyz')
        i = random.randrange(len(st))
        c = random.choice('abcdefghijklmnopqrstuvwxyz0123456789')
        return st[:i] + c + st[i+1:]

    def ins_char(st: str) -> str:
        pos = random.randrange(len(st) + 1)
        c = random.choice('abcdefghijklmnopqrstuvwxyz0123456789')
        return st[:pos] + c + st[pos:]

    def del_char(st: str) -> str:
        if not st:
            return st
        if len(st) == 1:
            return random.choice(['a', '1', 'x'])
        pos = random.randrange(len(st))
        return st[:pos] + st[pos+1:]

    def swap_prefix(st: str) -> str:
        if st.startswith('al_'):
            return 'xl_' + st[3:]
        else:
            return 'al_' + st

    def replace_dash(st: str) -> str:
        if '-' in st:
            return st.replace('-', 'x', 1)
        else:
            return st + 'x'

    def append_suffix(st: str) -> str:
        return st + random.choice(['x', 'y', 'z', '-1', 'a'])

    def remove_underscore(st: str) -> str:
        if '_' in st:
            return st.replace('_', '', 1)
        else:
            return st

    def break_structure(st: str) -> str:
        if '-' in st:
            return st.replace('-', '', 1)
        else:
            return st + random.choice('-_')

    def to_xb_suffix(st: str) -> str:
        if '-' in st:
            pre, _ = st.rsplit('-', 1)
            return pre + '-xb'
        else:
            return st + '-xb'

    options = [
        sub_char,
        ins_char,
        del_char,
        swap_prefix,
        replace_dash,
        append_suffix,
        remove_underscore,
        break_structure,
        to_xb_suffix,
    ]

    func = random.choice(options)
    return func(s)
